        <!-- Sidebar de Usuários -->
        <div class="col-md-4">
            <div class="card card-dark shadow mb-3">
                <div class="card-header text-center">
                    <h5 class="text-white">Conectado como: <?= htmlspecialchars($current_username) ?></h5>
                </div>
                <div class="card-body">
                    <h6>Selecionar Contato:</h6>
                    <ul class="list-group" id="user-list">
                        <?php if (empty($other_users)): ?>
                            <li class="list-group-item text-center">Nenhum outro usuário cadastrado.</li>
                        <?php else: ?>
                            <?php foreach ($other_users as $user): ?>
                                <!-- Clique para selecionar e iniciar chat com este usuário -->
                                <li class="list-group-item d-flex justify-content-between align-items-center" data-user-id="<?= $user['id'] ?>" data-username="<?= htmlspecialchars($user['username']) ?>">
                                    <?= htmlspecialchars($user['username']) ?>
                                    <span class="btn btn-sm btn-outline-light">Chatear</span>
                                </li>
                            <?php endforeach; ?>
                        <?php endif; ?>
                    </ul>
                </div>
            </div>
        </div>

        <!-- Área Principal do Chat -->
        <div class="col-md-8">
            <div class="card shadow">
                <div class="chat-header p-3 text-center">
                    <h4>Conversando com: <span id="chat-target-user">Ninguém selecionado</span></h4>
                    <a href="logout.php" class="text-white btn btn-sm float-right">Logout</a>
                </div>

                <div id="chat-window">
