<script>
    // Lógica simples de seleção de usuário via JavaScript
    document.addEventListener('DOMContentLoaded', function() {
        const userItems = document.querySelectorAll('#user-list .list-group-item');
        const chatTarget = document.getElementById('chat-target-user');

        userItems.forEach(item => {
            item.addEventListener('click', function() {
                const username = this.getAttribute('data-username');
                chatTarget.textContent = username;
                // Em um sistema real, você mudaria o ID de chat ou atualizaria o destinatário
                alert("Você selecionou " + username + " para conversar!");
            });
        });
    });
</script>
